import{_ as s,O as r,H as i,f as l,i as d,k as n,b as t,j as o}from"./chunks/framework.DfbB1OsU.js";const y=JSON.parse('{"title":"Still a long way to go","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Still a long way to go | trendEcon"}],["meta",{"property":"og:description","content":"Daily economic indicators from Google searches"}],["meta",{"property":"og:url","content":"https://www.trendecon.org/blog/mobility"}],["meta",{"name":"twitter:title","content":"Still a long way to go | trendEcon"}],["meta",{"name":"twitter:description","content":"Daily economic indicators from Google searches"}]]},"headers":[],"relativePath":"blog/mobility.md","filePath":"blog/mobility.md"}'),c={name:"blog/mobility.md"};function p(h,e,m,g,u,b){const a=r("SeriesChart");return i(),l("div",null,[e[0]||(e[0]=d('<h1 id="still-a-long-way-to-go" tabindex="-1">Still a long way to go <a class="header-anchor" href="#still-a-long-way-to-go" aria-label="Permalink to &quot;Still a long way to go&quot;">​</a></h1><div class="byline"><span class="byline-author">Stefan Legge</span><span class="byline-date">26 August 2020</span></div><p>Many tasks people need to get done have not changed in centuries: getting food, finding a place to sleep, treating illness, or moving from one place to another. The business theorist Clayton Christensen built a theory of the <a href="https://hbr.org/2016/09/know-your-customers-jobs-to-be-done" target="_blank" rel="noreferrer">jobs to be done</a> around this. His key observation was that the tools people use to get these jobs done change far more often than the jobs themselves.</p><p>For mobility, people changed their main mode of transport whenever new technologies, the train, the car, the airplane, allowed and encouraged it. Most recently, the Covid-19 pandemic made some forms of transport less attractive, and health concerns meant many people travelled far less. Data from KOF showed that the average distance travelled had largely recovered from its low point at the end of March, which raises a question: did the pandemic lead to lasting changes in how people travel? Do they keep using bikes and cars instead of public transport?</p><p>trendEcon sheds light on this. Below we show searches for <em>Velo kaufen</em> (buy a bike) and <em>Auto kaufen</em> (buy a car). Interest in bikes peaked while interest in cars held up.</p>',5)),n(a,{src:"https://cdn.jsdelivr.net/gh/trendecon/media-content@master/data_examples/article_3_a.csv",ids:["Velo kaufen","Auto kaufen"],title:"Buying a bike vs a car"}),e[1]||(e[1]=t("p",null,[o("Public transport tells a different story. Searches for "),t("em",null,"Bus Ticket"),o(" and "),t("em",null,"Zugticket"),o(" (train ticket) plummeted and stayed well below pre-Corona levels.")],-1)),n(a,{src:"https://cdn.jsdelivr.net/gh/trendecon/media-content@master/data_examples/article_3_a.csv",ids:["Bus Ticket","Zugticket"],title:"Public transport tickets"}),e[2]||(e[2]=t("p",null,"Covid-19 caused some dramatic changes in people's lives and mobility preferences. Whether the elevated interest in bikes and the reduced interest in public transport would last remained to be seen.",-1))])}const w=s(c,[["render",p]]);export{y as __pageData,w as default};
